<template>
  <section class="flow-layout">
    <el-card><div class="section-heading"><h2>循环流程</h2><el-button :disabled="locked" @click="$emit('new')">新建</el-button></div><el-input v-model="search" placeholder="筛选流程" clearable /><div v-for="f in filtered" :key="f.id" class="flow-card" :class="{active:f.id===flow.id}" @click="$emit('select',f)"><strong>{{ f.name || f.id }}</strong><small>{{ f.id }} · {{ (f.state_ids||[]).length }} 个 State</small></div></el-card>
    <el-card><el-form size="small" label-width="105px" :disabled="locked"><div class="form-grid"><el-form-item label="流程 ID"><el-input v-model="flow.id" :disabled="persisted" /></el-form-item><el-form-item label="名称"><el-input v-model="flow.name" /></el-form-item><el-form-item label="完成次数"><el-input-number v-model="flow.completion_count" :min="1" :max="1000" /></el-form-item><el-form-item label="最大轮数"><el-input-number v-model="flow.max_rounds" :min="1" :max="10000" /></el-form-item><el-form-item label="超时（秒）"><el-input-number v-model="flow.timeout_seconds" :min="1" :max="3600" /></el-form-item><el-form-item label="轮间等待 ms"><el-input-number v-model="flow.poll_ms" :min="0" :max="10000" /></el-form-item><el-form-item label="只识别"><el-switch v-model="flow.dry_run" /></el-form-item></div>
      <el-form-item label="显式 State"><el-select v-model="flow.state_ids" multiple filterable placeholder="选择参与流程的 State"><el-option v-for="s in states" :key="s.id" :label="s.name+' · '+s.id" :value="s.id" /></el-select></el-form-item>
      <el-form-item label="按分组添加"><el-select v-model="group" placeholder="选择分组"><el-option label="未分组" value="" /><el-option v-for="g in groups" :key="g.name" :label="g.name" :value="g.name" /></el-select><el-button @click="addGroup">添加当前分组</el-button></el-form-item>
    </el-form><p class="hint">成功 {{ counts.success }} / 失败 {{ counts.failure }} / 兜底 {{ counts.fallback }} · 新增 State 不会自动加入已保存流程。</p>
    <div class="reference-cards"><button v-for="s in selectedStates" :key="s.id" class="reference-card" @click="$emit('edit',s)"><img v-if="s.recognition.type==='image'" :src="'/assets/'+s.recognition.asset" /><span>{{ s.name }}</span><small>{{ s.role }}</small></button></div>
    <div class="button-row"><el-button type="primary" :disabled="locked" @click="$emit('save')">保存流程</el-button><el-button type="success" :disabled="locked||!serial||!flow.state_ids.length" @click="$emit('start')">保存并启动</el-button><el-button :disabled="locked||!persisted" @click="$emit('copy')">复制</el-button><el-button type="danger" :disabled="locked||!persisted" @click="$emit('delete')">删除</el-button></div><el-collapse><el-collapse-item title="配置 JSON 预览" name="config"><pre>{{ JSON.stringify(flow,null,2) }}</pre></el-collapse-item></el-collapse></el-card>
  </section>
</template>
<script>
export default {props:{flows:Array,flow:Object,states:Array,groups:Array,locked:Boolean,serial:String},data:()=>({search:'',group:''}),computed:{filtered(){return this.flows.filter(f=>(f.name+' '+f.id).toLowerCase().includes(this.search.toLowerCase()));},persisted(){return this.flows.some(f=>f.id===this.flow.id);},selectedStates(){return this.states.filter(s=>this.flow.state_ids.includes(s.id));},counts(){const counts={success:0,failure:0,fallback:0};this.selectedStates.forEach(s=>{if(s.role in counts)counts[s.role]++;});return counts;}},methods:{addGroup(){this.flow.state_ids=[...new Set([...this.flow.state_ids,...this.states.filter(s=>(s.group||'')===this.group).map(s=>s.id)])];}}};
</script>
